SELECT banner_title
FROM sys_industry_ver_conf
WHERE
    industry_code = #{industryCode}
    and app_ver_code = #{appVerCode}
    and accept_node = #{platformCode}
    and delete_flag = 0

mapper.delete:
delete  from sys_info_set
where
    type = #{type}

    and creator = #{createBy}


    and tenant_id = #{tenantId}


    and industry_code = #{industryCode}


    and app_ver_code = #{appVerCode}


    and dept_id = #{deptId}
